// Turns docs/design/tokens.json into lib/core/theme/tokens/design_tokens.dart
// (specs/008.5-m21-design-refresh, contracts/design-tokens.md). Pure: the CLI
// in gen_tokens.dart reads and writes the files, and the repo test runs this
// in memory to check the committed file.
import 'package:dart_style/dart_style.dart';

/// The header every generated file starts with.
const generatedHeader =
    '// GENERATED by tool/design/gen_tokens.dart from docs/design/tokens.json. '
    'Do not edit.';

/// Formats generated source the way `dart format` does.
String formatTokens(String source) =>
    DartFormatter(languageVersion: DartFormatter.latestLanguageVersion)
        .format(source);

/// The Dart source of the token classes for [json], unformatted. Throws a
/// [FormatException] naming the key of any value it can't read.
String generateTokens(Map<String, Object?> json) => _Generator(json).run();

/// Top-level keys that are documentation or owned elsewhere: digits by
/// NumberFormatter, fonts by pubspec.yaml.
const _skippedGroups = {'font', 'digits'};

/// Keys under `motion` that are not generated: hop times are the engine's
/// per-line tunables (constitution VIII), and `reducedMotion` is a note.
const _skippedMotion = {'moneyHop', 'reducedMotion'};

const _colorGroups = {
  'color': '',
  'dashboard': 'dashboard',
  'scene': 'scene',
  'character': 'character',
};

const _curves = {
  'linear': 'Curves.linear',
  'easeIn': 'Curves.easeIn',
  'easeOut': 'Curves.easeOut',
  'easeInOut': 'Curves.easeInOut',
  'easeInCubic': 'Curves.easeInCubic',
  'easeOutCubic': 'Curves.easeOutCubic',
  'easeInOutCubic': 'Curves.easeInOutCubic',
};

final class _Generator {
  _Generator(this.json);

  final Map<String, Object?> json;

  final _colors = StringBuffer();
  final _colorFields = <String>[];
  final _stations = StringBuffer();
  final _type = StringBuffer();
  final _typeNames = <String>[];
  final _families = <String>{};
  final _radius = StringBuffer();
  final _lip = StringBuffer();
  final _ring = StringBuffer();
  final _space = StringBuffer();
  final _layout = StringBuffer();
  final _motion = StringBuffer();

  String run() {
    for (final MapEntry(:key, :value) in json.entries) {
      if (_isNote(key, value) || _skippedGroups.contains(key)) continue;
      switch (key) {
        case 'color' || 'dashboard' || 'scene' || 'character':
          _colorGroup(key, _map(value, key));
        case 'money_note':
          _moneyNotes(_map(value, key));
        case 'denomination':
          _denominations(_map(value, key));
        case 'station':
          _stationList(_list(value, key));
        case 'type':
          _typeStyles(_map(value, key));
        case 'radius':
          _numbers(_radius, _map(value, key), key, (k) => _camel(k));
        case 'space':
          _numbers(_space, _map(value, key), key, (k) => 's$k');
        case 'lip':
          _lips(_map(value, key));
        case 'ring':
          _rings(_map(value, key));
        case 'layout':
          _layoutGroup(_map(value, key), 'layout', '');
        case 'motion':
          _motionGroup(_map(value, key));
        default:
          throw FormatException('$key: unknown token group');
      }
    }
    return _source();
  }

  /// Documentation: text or a list of it, under a `$…`, `…_rules`,
  /// `…_note` or `use` key. `money_note` holds colours, so it isn't one.
  static bool _isNote(String key, Object? value) =>
      value is! Map &&
      (key.startsWith(r'$') ||
          key.endsWith('_rules') ||
          key.endsWith('_note') ||
          key == 'use');

  // Colours.

  void _colorGroup(String group, Map<String, Object?> values) {
    final prefix = _colorGroups[group]!;
    for (final MapEntry(:key, :value) in values.entries) {
      final path = '$group.$key';
      final name = _join(prefix, key);
      switch (value) {
        case String():
          _color(name, value, path);
        case List<Object?>():
          _colors.writeln('  static const $name = <Color>[');
          for (final (i, item) in value.indexed) {
            _colors.writeln('    ${_parseColor(item, '$path[$i]')},');
          }
          _colors.writeln('  ];');
        case {'color': final Object? color, 'opacity': final num opacity}:
          _color(name, color, '$path.color');
          _colors.writeln('  static const double ${name}Opacity = $opacity;');
        default:
          throw FormatException('$path: unreadable value "$value"');
      }
    }
  }

  void _moneyNotes(Map<String, Object?> notes) {
    for (final MapEntry(:key, :value) in notes.entries) {
      final note = _map(value, 'money_note.$key');
      final name = _join('note', key);
      _color(name, note['bg'], 'money_note.$key.bg');
      _color('${name}Lip', note['lip'], 'money_note.$key.lip');
      _color('${name}Text', note['text'], 'money_note.$key.text');
    }
  }

  void _denominations(Map<String, Object?> values) {
    for (final MapEntry(:key, :value) in values.entries) {
      final suffix = key.contains('.') ? '${key.replaceAll('.', '')}0' : key;
      _color(
        'denom$suffix',
        _map(value, 'denomination.$key')['bg'],
        'denomination.$key.bg',
      );
    }
  }

  void _color(String name, Object? value, String path) {
    _colors.writeln('  static const $name = ${_parseColor(value, path)};');
    _colorFields.add(name);
  }

  void _stationList(List<Object?> stations) {
    for (final (i, raw) in stations.indexed) {
      final station = _map(raw, 'station[$i]');
      final bg = _parseColor(station['bg'], 'station[$i].bg');
      final letter = _parseColor(station['letter'], 'station[$i].letter');
      _stations.writeln('    (bg: $bg, letter: $letter),');
    }
  }

  // Type.

  void _typeStyles(Map<String, Object?> styles) {
    for (final MapEntry(:key, :value) in styles.entries) {
      final path = 'type.$key';
      final style = _map(value, path);
      final name = _camel(key);
      final family = _string(
        style['family'],
        '$path.family',
      ).replaceAll(' ', '');
      _families.add(family);
      final weight = _int(style['weight'], '$path.weight');
      final size = _number(style['size'], '$path.size');
      final height = _number(style['lineHeight'], '$path.lineHeight');
      for (final field in style.keys) {
        if (!const {
          'family',
          'weight',
          'size',
          'lineHeight',
          'min',
          'range',
          'weights',
          'use',
        }.contains(field)) {
          throw FormatException('$path.$field: unknown type field');
        }
      }
      _type
        ..writeln('  static const $name = TextStyle(')
        ..writeln("    fontFamily: '$family',")
        ..writeln('    fontSize: ${_num(size)},')
        ..writeln('    fontWeight: FontWeight.w$weight,')
        ..writeln("    fontVariations: [FontVariation('wght', $weight)],")
        ..writeln('    height: ${_num(height)},')
        ..writeln('    leadingDistribution: TextLeadingDistribution.even,')
        ..writeln('  );');
      _typeNames.add(name);
      final min = style['min'];
      if (min != null) {
        _type.writeln(
          '  static const double ${name}MinSize = '
          '${_num(_number(min, '$path.min'))};',
        );
      }
    }
  }

  // Shape.

  void _numbers(
    StringBuffer out,
    Map<String, Object?> values,
    String group,
    String Function(String key) name,
  ) {
    for (final MapEntry(:key, :value) in values.entries) {
      out.writeln(
        '  static const double ${name(key)} = '
        '${_num(_number(value, '$group.$key'))};',
      );
    }
  }

  void _lips(Map<String, Object?> lips) {
    for (final MapEntry(:key, :value) in lips.entries) {
      final path = 'lip.$key';
      final lip = _map(value, path);
      final name = _camel(key);
      final y = _num(_number(lip['y'], '$path.y'));
      final color = _parseColor(lip['color'], '$path.color');
      _lip
        ..writeln('  static const $name = BoxShadow(')
        ..writeln('    offset: Offset(0, $y),')
        ..writeln('    color: $color,')
        ..writeln('  );')
        ..writeln('  static const double ${name}Depth = $y;');
    }
  }

  void _rings(Map<String, Object?> rings) {
    for (final MapEntry(:key, :value) in rings.entries) {
      final path = 'ring.$key';
      final ring = _map(value, path);
      final name = _camel(key);
      if (ring.containsKey('width')) {
        _ring
          ..writeln('  static const $name = RingSpec(')
          ..writeln(
            '    width: ${_num(_number(ring['width'], '$path.width'))},',
          )
          ..writeln('    color: ${_parseColor(ring['color'], '$path.color')},')
          ..writeln('    inside: ${ring['inset'] == true},')
          ..writeln('    dashed: ${ring['dashed'] == true},')
          ..writeln('  );');
        continue;
      }
      for (final MapEntry(key: field, value: v) in ring.entries) {
        final fieldName = _join(name, field);
        if (v is num) {
          _ring.writeln('  static const double $fieldName = ${_num(v)};');
        } else {
          _ring.writeln(
            '  static const $fieldName = '
            '${_parseColor(v, '$path.$field')};',
          );
        }
      }
    }
  }

  // Layout.

  void _layoutGroup(Map<String, Object?> values, String path, String prefix) {
    for (final MapEntry(:key, :value) in values.entries) {
      final at = '$path.$key';
      // The seat rows read as `tripNear`, not `tripFacesNear`.
      final name = key == 'faces' ? prefix : _join(prefix, key);
      switch (value) {
        case {'x': final num x, 'y': final num y} when value.length == 2:
          _layout.writeln(
            '  static const $name = Offset(${_num(x)}, ${_num(y)});',
          );
        case Map<String, Object?>(:final containsKey) when containsKey('r'):
          _faceRow(name, value, at);
        case Map<String, Object?>():
          _layoutGroup(value, at, name);
        case List<Object?>():
          final items = [for (final v in value) _num(_number(v, at))];
          _layout.writeln(
            '  static const $name = <double>[${items.join(', ')}];',
          );
        case num() when key.endsWith('Ms'):
          _layout.writeln(
            '  static const ${name.substring(0, name.length - 2)} = '
            'Duration(milliseconds: ${value.toInt()});',
          );
        case int() when key.startsWith('max'):
          _layout.writeln('  static const int $name = $value;');
        case num():
          _layout.writeln('  static const double $name = ${_num(value)};');
        default:
          throw FormatException('$at: unreadable value "$value"');
      }
    }
  }

  void _faceRow(String name, Map<String, Object?> row, String path) {
    final xs = [
      for (final x in _list(row['x'], '$path.x')) _num(_number(x, '$path.x')),
    ];
    _layout
      ..writeln('  static const $name = FaceRowSpec(')
      ..writeln('    r: ${_num(_number(row['r'], '$path.r'))},')
      ..writeln('    scale: ${_num(_number(row['scale'], '$path.scale'))},')
      ..writeln('    y: ${_num(_number(row['y'], '$path.y'))},')
      ..writeln('    x: <double>[${xs.join(', ')}],')
      ..writeln('    tag: ${_num(_number(row['tag'], '$path.tag'))},')
      ..writeln('  );');
  }

  // Motion.

  void _motionGroup(Map<String, Object?> values) {
    for (final MapEntry(:key, :value) in values.entries) {
      if (_skippedMotion.contains(key) || _isNote(key, value)) continue;
      final path = 'motion.$key';
      final motion = _map(value, path);
      final name = _camel(key);
      for (final MapEntry(key: field, value: v) in motion.entries) {
        final at = '$path.$field';
        switch (field) {
          case 'ms':
            _motion.writeln(
              '  static const $name = '
              'Duration(milliseconds: ${_int(v, at)});',
            );
          case 'curve':
            _motion.writeln('  static const ${name}Curve = ${_curve(v, at)};');
          case 'stagger' || 'holdMs':
            final suffix = field == 'holdMs' ? 'Hold' : 'Stagger';
            _motion.writeln(
              '  static const $name$suffix = '
              'Duration(milliseconds: ${_int(v, at)});',
            );
          default:
            final fieldName = _join(name, field);
            switch (v) {
              case bool():
                _motion.writeln('  static const bool $fieldName = $v;');
              case num():
                _motion.writeln(
                  '  static const double $fieldName = ${_num(v)};',
                );
              case List<Object?>():
                final items = [for (final i in v) _num(_number(i, at))];
                _motion.writeln(
                  '  static const $fieldName = <double>[${items.join(', ')}];',
                );
              default:
                throw FormatException('$at: unreadable value "$v"');
            }
        }
      }
    }
  }

  String _curve(Object? value, String path) {
    final text = _string(value, path);
    final known = _curves[text];
    if (known != null) return known;
    final back = RegExp(r'^easeOutBack\(([0-9.]+)\)$').firstMatch(text);
    if (back != null) return 'EaseOutBack(${back.group(1)})';
    throw FormatException('$path: unreadable curve "$text"');
  }

  // Output.

  String _source() {
    final out = StringBuffer()
      ..writeln(generatedHeader)
      ..writeln()
      ..writeln("import 'package:material_ui/material_ui.dart';")
      ..writeln("import 'package:wassal/core/theme/tokens/curves.dart';")
      ..writeln()
      ..writeln('/// The palette. Text colour is never part of a type token.')
      ..writeln('abstract final class ColorTokens {')
      ..write(_colors)
      ..writeln()
      ..writeln(
        '  /// Every single colour by its name (the gallery\'s swatches).',
      )
      ..writeln('  static const named = <String, Color>{');
    for (final f in _colorFields) {
      out.writeln("    '$f': $f,");
    }
    out
      ..writeln('  };')
      ..writeln('}')
      ..writeln()
      ..writeln('/// A station tag: its fill and its letter.')
      ..writeln('typedef StationPair = ({Color bg, Color letter});')
      ..writeln()
      ..writeln('/// Stations by their order on the line.')
      ..writeln('abstract final class StationColors {')
      ..writeln('  static const all = <StationPair>[')
      ..write(_stations)
      ..writeln('  ];')
      ..writeln('}')
      ..writeln()
      ..writeln('/// The type scale. Each style sets its weight twice, so the')
      ..writeln("/// variable fonts' wght axis follows it on every renderer.")
      ..writeln('abstract final class TypeTokens {');
    for (final family in _families) {
      out.writeln("  static const ${_camel(family)} = '$family';");
    }
    out
      ..write(_type)
      ..writeln('  static const all = <TextStyle>[${_typeNames.join(', ')}];')
      ..writeln('}')
      ..writeln()
      ..writeln('abstract final class RadiusTokens {')
      ..write(_radius)
      ..writeln('}')
      ..writeln()
      ..writeln(
        '/// Solid, unblurred shadows straight down; a press removes them.',
      )
      ..writeln('abstract final class LipTokens {')
      ..write(_lip)
      ..writeln('}')
      ..writeln()
      ..writeln('/// An outline drawn inside or outside a shape.')
      ..writeln('final class RingSpec {')
      ..writeln('  const RingSpec({')
      ..writeln('    required this.width,')
      ..writeln('    required this.color,')
      ..writeln('    required this.inside,')
      ..writeln('    required this.dashed,')
      ..writeln('  });')
      ..writeln()
      ..writeln('  final double width;')
      ..writeln('  final Color color;')
      ..writeln('  final bool inside;')
      ..writeln('  final bool dashed;')
      ..writeln('}')
      ..writeln()
      ..writeln('abstract final class RingTokens {')
      ..write(_ring)
      ..writeln('}')
      ..writeln()
      ..writeln('abstract final class SpaceTokens {')
      ..write(_space)
      ..writeln('}')
      ..writeln()
      ..writeln('/// A row of seats in the trip scene, on the 390-wide frame.')
      ..writeln('final class FaceRowSpec {')
      ..writeln('  const FaceRowSpec({')
      ..writeln('    required this.r,')
      ..writeln('    required this.scale,')
      ..writeln('    required this.y,')
      ..writeln('    required this.x,')
      ..writeln('    required this.tag,')
      ..writeln('  });')
      ..writeln()
      ..writeln("  /// The face's radius at this row's scale.")
      ..writeln('  final double r;')
      ..writeln('  final double scale;')
      ..writeln('  final double y;')
      ..writeln('  final List<double> x;')
      ..writeln("  /// The station tag's size.")
      ..writeln('  final double tag;')
      ..writeln('}')
      ..writeln()
      ..writeln('abstract final class LayoutTokens {')
      ..write(_layout)
      ..writeln('}')
      ..writeln()
      ..writeln('abstract final class MotionTokens {')
      ..write(_motion)
      ..writeln('}')
      ..writeln()
      ..write(_extension());
    return out.toString();
  }

  String _extension() {
    final out = StringBuffer()
      ..writeln('/// The palette as a theme extension: widgets read')
      ..writeln('/// `context.tokens`.')
      ..writeln('@immutable')
      ..writeln('class WassalTokens extends ThemeExtension<WassalTokens> {')
      ..writeln('  const WassalTokens({');
    for (final f in _colorFields) {
      out.writeln('    required this.$f,');
    }
    out
      ..writeln('    required this.stations,')
      ..writeln('  });')
      ..writeln()
      ..writeln('  static const standard = WassalTokens(');
    for (final f in _colorFields) {
      out.writeln('    $f: ColorTokens.$f,');
    }
    out
      ..writeln('    stations: StationColors.all,')
      ..writeln('  );')
      ..writeln();
    for (final f in _colorFields) {
      out.writeln('  final Color $f;');
    }
    out
      ..writeln('  final List<StationPair> stations;')
      ..writeln()
      ..writeln('  @override')
      ..writeln('  WassalTokens copyWith({');
    for (final f in _colorFields) {
      out.writeln('    Color? $f,');
    }
    out
      ..writeln('    List<StationPair>? stations,')
      ..writeln('  }) => WassalTokens(');
    for (final f in _colorFields) {
      out.writeln('    $f: $f ?? this.$f,');
    }
    out
      ..writeln('    stations: stations ?? this.stations,')
      ..writeln('  );')
      ..writeln()
      ..writeln('  @override')
      ..writeln('  WassalTokens lerp(WassalTokens? other, double t) {')
      ..writeln('    if (other == null) return this;')
      ..writeln('    return WassalTokens(');
    for (final f in _colorFields) {
      out.writeln('      $f: Color.lerp($f, other.$f, t)!,');
    }
    out
      ..writeln('      stations: t < 0.5 ? stations : other.stations,')
      ..writeln('    );')
      ..writeln('  }')
      ..writeln('}')
      ..writeln()
      ..writeln('extension WassalTokensContext on BuildContext {')
      ..writeln('  WassalTokens get tokens =>')
      ..writeln(
        '      Theme.of(this).extension<WassalTokens>() ?? '
        'WassalTokens.standard;',
      )
      ..writeln('}');
    return out.toString();
  }
}

// Readers. Each names the key it reads when the value is wrong.

Map<String, Object?> _map(Object? value, String path) =>
    value is Map<String, Object?>
    ? value
    : throw FormatException('$path: expected an object, got "$value"');

List<Object?> _list(Object? value, String path) => value is List<Object?>
    ? value
    : throw FormatException('$path: expected a list, got "$value"');

String _string(Object? value, String path) => value is String
    ? value
    : throw FormatException('$path: expected text, got "$value"');

int _int(Object? value, String path) => value is int
    ? value
    : throw FormatException('$path: expected a whole number, got "$value"');

/// A number, or text such as "22–26 (24)", which reads as its bracketed
/// value.
num _number(Object? value, String path) {
  if (value is num) return value;
  if (value is String) {
    final bracketed = RegExp(r'\(([0-9.]+)\)').firstMatch(value);
    final parsed = num.tryParse(bracketed?.group(1) ?? value);
    if (parsed != null) return parsed;
  }
  throw FormatException('$path: unreadable number "$value"');
}

final _hex = RegExp(r'^#([0-9A-Fa-f]{6})$');
final _rgba = RegExp(
  r'^rgba\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*([0-9.]+)\s*\)$',
);

/// `#RRGGBB` or `rgba(r,g,b,a)` as `Color(0xAARRGGBB)`.
String _parseColor(Object? value, String path) {
  if (value is String) {
    final hex = _hex.firstMatch(value);
    if (hex != null) return 'Color(0xFF${hex.group(1)!.toUpperCase()})';
    final rgba = _rgba.firstMatch(value);
    if (rgba != null) {
      String byte(int v) => v.toRadixString(16).padLeft(2, '0').toUpperCase();
      final alpha = (double.parse(rgba.group(4)!) * 255).round();
      final rgb = [for (var i = 1; i <= 3; i++) int.parse(rgba.group(i)!)];
      if (alpha <= 255 && rgb.every((c) => c <= 255)) {
        return 'Color(0x${byte(alpha)}${rgb.map(byte).join()})';
      }
    }
  }
  throw FormatException('$path: unreadable colour "$value"');
}

/// A number as Dart source: whole numbers without a decimal point.
String _num(num value) =>
    value == value.roundToDouble() ? value.toInt().toString() : '$value';

/// `seat.hi` → `seatHi`, `new_dot` → `newDot`, `Readex Pro` → `readexPro`.
String _camel(String key) {
  final parts = key.split(RegExp(r'[._ ]')).where((p) => p.isNotEmpty).toList();
  return [
    parts.first[0].toLowerCase() + parts.first.substring(1),
    for (final p in parts.skip(1)) p[0].toUpperCase() + p.substring(1),
  ].join();
}

/// [key] camel-cased after [prefix]: `dashboard` + `bg` → `dashboardBg`.
String _join(String prefix, String key) {
  final name = _camel(key);
  return prefix.isEmpty
      ? name
      : prefix + name[0].toUpperCase() + name.substring(1);
}
